//! One live capture: reader -> clean_lines -> DeltaState every tick; streams only changes; keeps the partial current.
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::time::{Duration, Instant};
use serde::Serialize;
use crate::capture_delta::{CaptionDelta, DeltaState};
use crate::capture_model::{AxAppTree, AxReadError};
use crate::capture_readers::CaptionReader;
use crate::capture_store::{self, FinalMeta, FinalizedNote, PartialHeader, PartialWriter, Row};
use crate::capture_validate::clean_lines;

const ROW_CLOSE_AFTER: Duration = Duration::from_secs(3);
const ROW_MAX_PENDING: Duration = Duration::from_secs(15);
const NO_SOURCE_AFTER: Duration = Duration::from_secs(8);
pub const MAX_ROWS: usize = 50_000;

pub trait SnapshotSource: Send { fn trusted(&self)->bool; fn read(&mut self,bundle_id:&str)->Result<Option<AxAppTree>,AxReadError>; }
pub struct MacSource;
impl SnapshotSource for MacSource { fn trusted(&self)->bool{crate::capture_ax_macos::is_trusted()} fn read(&mut self,b:&str)->Result<Option<AxAppTree>,AxReadError>{crate::capture_ax_macos::read_app_tree(b)} }

#[derive(Debug,Clone,Copy,PartialEq,Eq,Serialize)]#[serde(rename_all="snake_case")]pub enum CaptureState{Recording,NoSource,PermissionLost,Full,Stopped,#[allow(dead_code)] Error}
#[derive(Debug,Clone,PartialEq,Serialize)]#[serde(tag="type",rename_all="snake_case")]pub enum CaptureEvent{State{state:CaptureState,platform:Option<String>,detail:Option<String>},Append{row:u64,time:String,speaker:String,text:String},Replace{row:u64,text:String},Closed{row:u64}}
pub enum TickOutcome{Continue,PermissionLost,Full}
#[derive(Debug,Clone,PartialEq,Serialize)]#[serde(rename_all="camelCase")]pub struct StopResult{pub note:Option<FinalizedNote>,pub kept_partial:bool,pub reason:Option<String>}
struct Pending{first_seen:Instant,changed:Instant}
pub struct Session{header:PartialHeader,notes_root:PathBuf,writer:PartialWriter,delta:DeltaState,readers:Vec<Box<dyn CaptionReader>>,preferred:Option<usize>,platform:Option<&'static str>,rows:BTreeMap<u64,Row>,pending:BTreeMap<u64,Pending>,started:Instant,no_source_flagged:bool}
fn state(s:CaptureState,p:Option<&str>)->CaptureEvent{CaptureEvent::State{state:s,platform:p.map(str::to_string),detail:None}}
impl Session{
pub fn start(dir:&Path,notes_root:PathBuf,language:String,now_ms:i64,now:Instant,readers:Vec<Box<dyn CaptionReader>>)->Result<Session,String>{let header=PartialHeader{v:1,id:capture_store::new_session_id(now_ms),started_at_ms:now_ms,language,notes_root:notes_root.display().to_string()};let writer=PartialWriter::create(dir,&header)?;Ok(Session{header,notes_root,writer,delta:DeltaState::new(),readers,preferred:None,platform:None,rows:BTreeMap::new(),pending:BTreeMap::new(),started:now,no_source_flagged:false})}
pub fn id(&self)->&str{&self.header.id}pub fn started_at_ms(&self)->i64{self.header.started_at_ms}pub fn notes_root(&self)->&Path{&self.notes_root}
pub fn tick(&mut self,src:&mut dyn SnapshotSource,now:Instant,now_ms:i64,out:&mut Vec<CaptureEvent>)->TickOutcome{if !src.trusted(){return self.lose_permission(out)}self.flush_idle(now);let mut order:Vec<usize>=(0..self.readers.len()).collect();if let Some(p)=self.preferred{order.retain(|i|*i!=p);order.insert(0,p)}let mut found=None;for idx in order{match src.read(self.readers[idx].bundle_id()){Ok(Some(t))=>{if let Some(l)=self.readers[idx].read(&t){found=Some((idx,l));break}}Ok(None)|Err(AxReadError::CannotComplete)|Err(AxReadError::Unsupported)=>{},Err(AxReadError::PermissionDenied)=>return self.lose_permission(out)}}let Some((idx,lines))=found else{if self.rows.is_empty()&&!self.no_source_flagged&&now.duration_since(self.started)>=NO_SOURCE_AFTER{self.no_source_flagged=true;out.push(state(CaptureState::NoSource,None))}for d in self.delta.ingest(&[]){self.apply(d,now,now_ms,out)}return TickOutcome::Continue};self.preferred=Some(idx);let platform=self.readers[idx].platform();if self.platform!=Some(platform){self.platform=Some(platform);self.no_source_flagged=false;let _=self.writer.set_platform(platform);out.push(state(CaptureState::Recording,Some(platform)))}for d in self.delta.ingest(&clean_lines(lines)){self.apply(d,now,now_ms,out)}if self.rows.len()>=MAX_ROWS{let _=self.close_out();out.push(state(CaptureState::Full,self.platform));return TickOutcome::Full}TickOutcome::Continue}
fn lose_permission(&mut self,out:&mut Vec<CaptureEvent>)->TickOutcome{let _=self.close_out();out.push(state(CaptureState::PermissionLost,self.platform));TickOutcome::PermissionLost}
fn apply(&mut self,d:CaptionDelta,now:Instant,now_ms:i64,out:&mut Vec<CaptureEvent>){match d{CaptionDelta::Append{row,speaker,text}=>{let time=capture_store::local_hms(now_ms);self.rows.insert(row,Row{time:time.clone(),speaker:speaker.clone(),text:text.clone()});self.pending.insert(row,Pending{first_seen:now,changed:now});out.push(CaptureEvent::Append{row,time,speaker,text})}CaptionDelta::Replace{row,speaker,new_text,..}=>{let time=capture_store::local_hms(now_ms);let r=self.rows.entry(row).or_insert(Row{time,speaker:speaker.clone(),text:String::new()});r.speaker=speaker;r.text=new_text.clone();if let Some(p)=self.pending.get_mut(&row){p.changed=now}out.push(CaptureEvent::Replace{row,text:new_text})}CaptionDelta::Closed{row}=>{self.flush_row(row);out.push(CaptureEvent::Closed{row})}}}
fn flush_row(&mut self,row:u64){if self.pending.remove(&row).is_some(){if let Some(r)=self.rows.get(&row){let _=self.writer.append_row(r);}}}
fn flush_idle(&mut self,now:Instant){let due:Vec<u64>=self.pending.iter().filter(|(_,p)|now.duration_since(p.changed)>=ROW_CLOSE_AFTER||now.duration_since(p.first_seen)>=ROW_MAX_PENDING).map(|(k,_)|*k).collect();for r in due{self.flush_row(r)}}
pub fn close_out(&mut self)->Result<(),String>{let rows:Vec<u64>=self.pending.keys().copied().collect();for r in rows{self.flush_row(r)}self.writer.sync()}
pub fn finish(mut self,root:Result<PathBuf,String>,title:&str,now_ms:i64)->StopResult{let _=self.close_out();let partial=self.writer.path().to_path_buf();if self.rows.is_empty(){let _=std::fs::remove_file(&partial);return StopResult{note:None,kept_partial:false,reason:Some("empty".into())}}let rows:Vec<Row>=self.rows.values().cloned().collect();let title=capture_store::clean_title(title);let meta=FinalMeta{id:&self.header.id,title:&title,started_at_ms:self.header.started_at_ms,ended_at_ms:now_ms,platform:self.platform.unwrap_or("mic"),language:&self.header.language};match root.and_then(|r|capture_store::finalize(&r,Some(&partial),&meta,&rows)){Ok(note)=>StopResult{note:Some(note),kept_partial:false,reason:None},Err(e)=>StopResult{note:None,kept_partial:true,reason:Some(e)}}}}
#[cfg(test)]mod tests{use super::*;use crate::capture_model::AxNode;use std::collections::VecDeque;use std::sync::atomic::{AtomicUsize,Ordering};
fn scratch(t:&str)->PathBuf{static N:AtomicUsize=AtomicUsize::new(0);let d=std::env::temp_dir().join(format!("llmide-sess-{t}-{}-{}",std::process::id(),N.fetch_add(1,Ordering::Relaxed)));let _=std::fs::remove_dir_all(&d);std::fs::create_dir_all(&d).unwrap();d}
struct Fake{trusted:bool,teams:VecDeque<Result<Option<AxAppTree>,AxReadError>>}impl SnapshotSource for Fake{fn trusted(&self)->bool{self.trusted}fn read(&mut self,b:&str)->Result<Option<AxAppTree>,AxReadError>{if b!="com.microsoft.teams2"{return Ok(None)}self.teams.pop_front().unwrap_or(Ok(None))}}
fn teams(rows:&[(&str,&str)])->Result<Option<AxAppTree>,AxReadError>{let groups=rows.iter().map(|(s,t)|AxNode{role:"AXGroup".into(),children:vec![AxNode{role:"AXStaticText".into(),value:Some(s.to_string()),..Default::default()},AxNode{role:"AXStaticText".into(),value:Some(t.to_string()),..Default::default()}],..Default::default()}).collect();let panel=AxNode{role:"AXGroup".into(),description:Some("Live captions".into()),children:groups,..Default::default()};Ok(Some(AxAppTree{bundle_id:"com.microsoft.teams2".into(),windows:vec![AxNode{role:"AXWindow".into(),children:vec![panel],..Default::default()}]}))}
fn start(t:&str)->(Session,PathBuf,PathBuf,Instant){let(d,r)=(scratch(&format!("{t}-d")),scratch(&format!("{t}-r")));let t0=Instant::now();(Session::start(&d,r.clone(),"en".into(),1_762_335_000_000,t0,crate::capture_readers::all_readers()).unwrap(),d,r,t0)}
fn kinds(o:&[CaptureEvent])->Vec<&'static str>{o.iter().map(|e|match e{CaptureEvent::State{..}=>"state",CaptureEvent::Append{..}=>"append",CaptureEvent::Replace{..}=>"replace",CaptureEvent::Closed{..}=>"closed"}).collect()}
#[test]fn streams(){let(mut s,..)=start("stream");let t0=Instant::now();let mut src=Fake{trusted:true,teams:VecDeque::from(vec![teams(&[("Alice","Hello")]),teams(&[("Alice","Hello")]),teams(&[("Alice","Hello there.")])])};let mut out=Vec::new();s.tick(&mut src,t0,1,&mut out);assert_eq!(kinds(&out),vec!["state","append"]);out.clear();s.tick(&mut src,t0+Duration::from_millis(800),2,&mut out);assert!(out.is_empty());s.tick(&mut src,t0+Duration::from_millis(1600),3,&mut out);assert_eq!(out,vec![CaptureEvent::Replace{row:0,text:"Hello there.".into()}])}
#[test]fn no_source(){let(mut s,..)=start("nosrc");let t0=Instant::now();let mut src=Fake{trusted:true,teams:VecDeque::new()};let mut out=Vec::new();s.tick(&mut src,t0+Duration::from_secs(7),1,&mut out);assert!(out.is_empty());s.tick(&mut src,t0+Duration::from_secs(9),2,&mut out);s.tick(&mut src,t0+Duration::from_secs(10),3,&mut out);assert_eq!(out,vec![CaptureEvent::State{state:CaptureState::NoSource,platform:None,detail:None}])}
#[test]fn permission(){let(mut s,_d,root,_)=start("perm");let t0=Instant::now();let mut src=Fake{trusted:true,teams:VecDeque::from(vec![teams(&[("Alice","Hello.")])])};s.tick(&mut src,t0,1,&mut Vec::new());src.trusted=false;let mut out=Vec::new();assert!(matches!(s.tick(&mut src,t0+Duration::from_secs(1),2,&mut out),TickOutcome::PermissionLost));assert_eq!(kinds(&out),vec!["state"]);let r=s.finish(Ok(root.clone()),"Sync",1_762_335_060_000);let n=r.note.unwrap();assert_eq!(n.lines,1);assert!(std::fs::read_to_string(root.join(n.rel)).unwrap().contains("**Alice**: Hello."))}
#[test]fn idle_partial(){let(mut s,dir,..)=start("idle");let t0=Instant::now();let mut src=Fake{trusted:true,teams:VecDeque::from(vec![teams(&[("Alice","Hello.")]),teams(&[("Alice","Hello.")])])};s.tick(&mut src,t0,1,&mut Vec::new());s.tick(&mut src,t0+Duration::from_secs(4),2,&mut Vec::new());s.close_out().unwrap();let p=crate::capture_store::partial_path(&dir,s.id()).unwrap();assert_eq!(crate::capture_store::read_partial(&p).unwrap().rows.len(),1)}
#[test]fn empty(){let(s,dir,root,_)=start("empty");let id=s.id().to_string();let r=s.finish(Ok(root),"",1);assert!(r.note.is_none()&&!r.kept_partial);assert_eq!(r.reason.as_deref(),Some("empty"));assert!(!crate::capture_store::partial_path(&dir,&id).unwrap().exists())}
#[test]fn events(){assert_eq!(serde_json::to_string(&CaptureEvent::Append{row:3,time:"09:30:01".into(),speaker:"A".into(),text:"<b>x</b>".into()}).unwrap(),r#"{"type":"append","row":3,"time":"09:30:01","speaker":"A","text":"<b>x</b>"}"#);assert_eq!(serde_json::to_string(&CaptureEvent::State{state:CaptureState::PermissionLost,platform:None,detail:None}).unwrap(),r#"{"type":"state","state":"permission_lost","platform":null,"detail":null}"#)}}
